// ─── Featured tag IDs ─────────────────────────────────────────────────────────

export const getFeaturedTagIds = () => {
  try {
    const raw = app.forum?.attribute('avocadoFeaturedTags');
    return new Set((raw ? JSON.parse(raw) : []).map(String));
  } catch {
    return new Set();
  }
};

